        match = re.search(r'#(\d+)=IFCWALL\([^)]+\'([^\']+)\'', line)
        if match:
            current_wall = {'id': match.group(1), 'mark': match.group(2)}
    elif current_wall and 'PanelMark' in line:
        match = re.search(r'IFCLABEL\(\'([^\']+)\'\)', line)
        if match:
            current_wall['mark'] = match.group(1)
    elif current_wall and 'WallLine' in line:
        match = re.search(r'IFCLABEL\(\'([^\']+)\'\)', line)
        if match:
            current_wall['line'] = match.group(1)
    elif current_wall and 'ThicknessMm' in line:
        match = re.search(r'IFCREAL\(([\d.]+)\)', line)
        if match:
            current_wall['thickness_mm'] = float(match.group(1))
    elif current_wall and 'TopElevationMm' in line:
        match = re.search(r'IFCREAL\(([\d.]+)\)', line)
        if match:
            current_wall['top_z_mm'] = float(match.group(1))
    elif current_wall and 'StartStationMm' in line:
        match = re.search(r'IFCREAL\(([\d.]+)\)', line)
        if match:
            current_wall['s0_mm'] = float(match.group(1))
    elif current_wall and 'EndStationMm' in line:
