        if line == 'N':
            if panel.startswith('N1'):
                line = 'N1'
            elif panel.startswith('N2'):
                line = 'N2'
        elif line == 'E':
            if panel.startswith('E2'):
                line = 'E2'
        if line not in patches_by_line:
            patches_by_line[line] = {}
        if panel not in patches_by_line[line]:
            patches_by_line[line][panel] = {}
        patches_by_line[line][panel][(azimuth, band)] = cp

for line, panels in patches_by_line.items():
    print(f'Line {line}: {len(panels)} panels')
    for panel, data in sorted(panels.items()):
